import json,os,sys
root=sys.argv[1] if len(sys.argv)>1 else '.'
GROUP={'choice':'choice','tap-token':'tap','sort':'sort','word-bank':'build','detect':'detect'}
def opts(xs):return [{'id':'o%d'%(i+1),'text':t} for i,t in enumerate(xs)]
def choice(title,stim,options,right,rules,ref,expl):
    o=opts(options);return dict(kind='choice',title=title,stimulus=stim,payload={'options':o,'accepted':[o[i]['id'] for i in right],'cardinality':len(right)},ruleIds=rules,source_ref=ref,explanation=expl)
def tap(title,stim,tokens,right,rules,ref,expl,why=None):
    t=[{'id':'t%d'%(i+1),'text':x} for i,x in enumerate(tokens)];d=dict(kind='tap-token',title=title,stimulus=stim,payload={'tokens':t,'accepted':[[t[i]['id'] for i in right]],'cardinality':len(right)},ruleIds=rules,source_ref=ref,explanation=expl)
    if why:d['why_wrong']=why  # one line after a wrong answer; never names the answer word
    return d
def sort(title,stim,cats,items,rules,ref,expl):
    c=[{'id':'c%d'%(i+1),'label':x} for i,x in enumerate(cats)];it=[{'id':'i%d'%(i+1),'text':x} for i,(x,_) in enumerate(items)]
    return dict(kind='sort',title=title,stimulus=stim,payload={'items':it,'categories':c,'accepted':{it[i]['id']:c[k]['id'] for i,(_,k) in enumerate(items)}},ruleIds=rules,source_ref=ref,explanation=expl)
def bank(title,stim,pieces,seq,rules,ref,expl):
    p=[{'id':'p%d'%(i+1),'text':x} for i,x in enumerate(pieces)];return dict(kind='word-bank',title=title,stimulus=stim,payload={'pieces':p,'accepted':[[p[i]['id'] for i in seq]]},ruleIds=rules,source_ref=ref,explanation=expl)
def detect(title,stim,target,ok,steps=None,bad=None,rules=None,ref='',expl=''):
    pl={'verdict':{'accepted':'correct' if ok else 'wrong'},'target':target}
    if not ok:
        s=opts(steps);pl['broken_step']={'options':s,'accepted':[s[bad]['id']]}
    return dict(kind='detect',title=title,stimulus=stim,payload=pl,ruleIds=rules or [],source_ref=ref,explanation=expl)
