for lid,items in L.items():
    pre='b34-'+lid.replace('-','')+'-';n={}
    out=[]
    for it in items:
        g=GROUP[it['kind']];n[g]=n.get(g,0)+1
        row={'id':pre+g+'-'+str(n[g]).zfill(2),'origin':'bank','group':g,'topic':'bank'};row.update(it);out.append(row)
    json.dump({'note':'r7 2b: independent practice bank (Q6). Support kinds only; origin bank; not homework. Language QA pending.','items':out},open(os.path.join(root,'lessons',lid,'practice-bank.json'),'w'),ensure_ascii=False,indent=1)
    print(lid,len(out))
